-- Promoted from _drafts/001_iam_active_store_context_group_a.sql
-- Generated by tools/c45_supabase_migrate/bin/promote_drafts.dart

create table if not exists iam.stores (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references iam.tenants(id) on delete cascade,
  code text not null,
  display_name text not null,
  status text not null check (status in ('active', 'inactive')),
  created_at timestamptz not null default now(),
  unique (tenant_id, code),
  unique (tenant_id, id)
);

do $$
begin
  -- Guard for environments where iam.memberships was created without a
  -- composite PK/UNIQUE on (tenant_id, user_id). The FK below requires it.
  if exists (
    select 1
    from iam.memberships m
    group by m.tenant_id, m.user_id
    having count(*) > 1
  ) then
    raise exception using errcode = 'P0001',
      message = 'Duplicate rows detected in iam.memberships(tenant_id, user_id). Resolve duplicates before applying active-store context migration.';
  end if;

  if not exists (
    select 1
    from pg_constraint c
    join pg_class t on t.oid = c.conrelid
    join pg_namespace n on n.oid = t.relnamespace
    where n.nspname = 'iam'
      and t.relname = 'memberships'
      and c.contype in ('p', 'u')
      and c.conkey = array[
        (select attnum from pg_attribute where attrelid = t.oid and attname = 'tenant_id'),
        (select attnum from pg_attribute where attrelid = t.oid and attname = 'user_id')
      ]::smallint[]
  ) then
    alter table iam.memberships
      add constraint memberships_tenant_user_unique unique (tenant_id, user_id);
  end if;
end;
$$;

alter table iam.stores enable row level security;

drop policy if exists stores_member_read on iam.stores;
create policy stores_member_read on iam.stores
  for select
  to authenticated
  using (
    exists (
      select 1
      from iam.memberships m
      where m.tenant_id = stores.tenant_id
        and m.user_id = auth.uid()
    )
  );

-- Single-store era: store access = active store of an operational tenant + active membership.
-- Multi-store later: reintroduce scopes and change only this helper.
create or replace function iam.can_access_store(
  p_tenant_id uuid,
  p_store_id uuid,
  p_user_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = iam, pg_temp
as $$
  select exists (
    select 1
    from iam.stores s
    join iam.memberships m
      on m.tenant_id = s.tenant_id
    where s.tenant_id = p_tenant_id
      and s.id = p_store_id
      and s.status = 'active'
      and m.user_id = p_user_id
      and m.is_active
  );
$$;

revoke all on function iam.can_access_store(uuid, uuid, uuid) from public, anon, authenticated;

revoke all on iam.stores from public, anon;
grant select on iam.stores to authenticated;

